def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Use a slower moving average with asymmetric scoring
    alpha = 0.3  # slower update than original 0.5
    action = observation["action"]
    if action == "donate":
        score = 0.8  # smaller reward for donating
    else:
        score = -1.2  # larger penalty for not donating

    # Adjust score based on reciprocity with a twist: reward defection after defection
    if my_history:
        last_entry = my_history[-1]
        if last_entry["partner_action"] == "donate" and action == "donate":
            score += 0.2  # less reinforcement than original
        elif last_entry["partner_action"] != "donate" and action != "donate":
            score += 0.1  # mutual defection is less bad

    new_reputation = alpha * current_reputation + (1 - alpha) * score
    # Keep reputation bounded between -1 and 1
    new_reputation = max(-1.0, min(1.0, new_reputation))
    return new_reputation


def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Compute recent donation rate to us (last 15 rounds)
    recent = my_history[-15:] if len(my_history) >= 15 else my_history
    if recent:
        received = sum(1 for entry in recent if entry["partner_action"] == "donate")
        received_rate = received / len(recent)
    else:
        received_rate = 0.5

    # Compute our own recent donation rate (last 15 rounds)
    if recent:
        given = sum(1 for entry in recent if entry["action"] == "donate")
        given_rate = given / len(recent)
    else:
        given_rate = 0.5

    # Base threshold starts at 0.5 (neutral)
    threshold = 0.5

    # Adjust based on received donations: if we received a lot, be more generous
    if received_rate > 0.7:
        threshold -= 0.25
    elif received_rate < 0.3:
        threshold += 0.25

    # Adjust based on our own behavior: if we have been stingy, become stricter
    if given_rate > 0.7:
        threshold -= 0.15  # tend to cooperate more if already cooperating
    elif given_rate < 0.3:
        threshold += 0.15  # be stricter if we've been defecting

    # Add a forgiveness component: if we defected last round, lower threshold slightly
    if my_history:
        if my_history[-1]["action"] != "donate":
            threshold -= 0.05

    # Increasing strictness over rounds, but slower than original
    threshold += 0.05 * min(round_num / 200.0, 1.0)

    # Clamp threshold to [0,1]
    threshold = max(0.0, min(1.0, threshold))

    return recipient_reputation > threshold
